const jllConversions=(()=>{
  const storagePrefix='jll-google-ads-conversion:';
  const hasAlreadyFired=key=>{try{return sessionStorage.getItem(`${storagePrefix}${key}`)==='1'}catch(_){return false}};
  const remember=key=>{try{sessionStorage.setItem(`${storagePrefix}${key}`,'1')}catch(_){}}
  const emitOnce=(key,origin)=>{
    if(!key||hasAlreadyFired(key))return false;
    window.dataLayer=window.dataLayer||[];
    window.gtag=window.gtag||function(){window.dataLayer.push(arguments)};
    window.gtag('event','click_whatsapp',{conversion_origin:origin,send_to:'G-VHS20ZGDH3'});
    remember(key);
    return true;
  };
  return {
    trackNewConversation:conversationId=>emitOnce(`new_chat_conversation:${conversationId}`,'new_chat_conversation')
  };
})();

const areas={
  capital:{kicker:'RIO DE JANEIRO — CAPITAL',title:'Da Zona Sul à Zona Oeste',copy:'Atendimento em bairros residenciais e comerciais de toda a cidade.',places:['Barra da Tijuca','Recreio dos Bandeirantes','Jacarepaguá','Tijuca','Vila Isabel','Méier','Madureira','Campo Grande','Bangu','Copacabana','Ipanema','Leblon','Botafogo','Flamengo','Laranjeiras','Centro','Santa Teresa','Ilha do Governador']},
  metropolitana:{kicker:'REGIÃO METROPOLITANA',title:'Grande Rio conectado',copy:'Serviços agendados nas principais cidades ao redor da capital.',places:['Niterói','São Gonçalo','Itaboraí','Maricá','Tanguá','Rio Bonito','Cachoeiras de Macacu','Magé','Guapimirim','Duque de Caxias','São João de Meriti','Nilópolis']},
  baixada:{kicker:'BAIXADA FLUMINENSE',title:'Atendimento na Baixada',copy:'Deslocamento planejado para residências, condomínios e empresas.',places:['Nova Iguaçu','Duque de Caxias','Belford Roxo','São João de Meriti','Nilópolis','Mesquita','Queimados','Japeri','Seropédica','Paracambi','Itaguaí','Magé']},
  norte:{kicker:'NORTE FLUMINENSE',title:'Da costa ao interior',copy:'Atendimento sob consulta e agendamento nas cidades do Norte Fluminense.',places:['Campos dos Goytacazes','Macaé','Rio das Ostras','Carapebus','Quissamã','São João da Barra','São Francisco de Itabapoana','Conceição de Macabu']}
};

const renderArea=(key)=>{const area=areas[key];const kicker=document.querySelector('#area-kicker');if(!area||!kicker)return;kicker.textContent=area.kicker;document.querySelector('#area-title').textContent=area.title;document.querySelector('#area-copy').textContent=area.copy;document.querySelector('#area-list').innerHTML=area.places.map(place=>`<li>${place}</li>`).join('');document.querySelectorAll('.area-tabs button').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.area===key)))};

document.querySelectorAll('.area-tabs button').forEach(button=>button.addEventListener('click',()=>renderArea(button.dataset.area)));
renderArea('capital');

const menuButton=document.querySelector('.menu-toggle');
if(menuButton)menuButton.addEventListener('click',()=>{const header=document.querySelector('.site-header');const open=header.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});
document.querySelectorAll('#main-nav a').forEach(link=>link.addEventListener('click',()=>{document.querySelector('.site-header').classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));

fetch('/config.json').then(response=>response.json()).then(config=>{
  const cnpj=document.querySelector('#cnpj');if(cnpj)cnpj.textContent=`CNPJ: ${config.cnpj}`;
  const rawNumber=String(config.whatsappNumber||'').replace(/\D/g,'');
  const number=rawNumber&& !rawNumber.startsWith('55') ? `55${rawNumber}` : rawNumber;
  if(number){const schema=document.querySelector('#business-schema');if(schema){const data=JSON.parse(schema.textContent);data.telephone=`+${number}`;schema.textContent=JSON.stringify(data)}}
}).catch(()=>{});

const year=document.querySelector('#year');if(year)year.textContent=new Date().getFullYear();
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));

document.querySelectorAll('details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('details[open]').forEach(other=>{if(other!==item)other.open=false})}));

(() => {
  const storageKey = 'jll-chat-conversation';
  const state = { conversation: null, messages: [] };
  const saved = localStorage.getItem(storageKey);
  if (saved) { try { const session = JSON.parse(saved); if (session.conversation && session.expiresAt > Date.now()) state.conversation = session.conversation; else localStorage.removeItem(storageKey); } catch (_) { localStorage.removeItem(storageKey); } }
  const saveConversation = () => { if (state.conversation) localStorage.setItem(storageKey, JSON.stringify({ conversation: state.conversation, expiresAt: Date.now() + 15 * 60 * 1000 })); };
  const el = document.createElement('div');
  el.innerHTML = `<button class="chat-launcher" type="button" aria-label="Abrir chat para solicitar orçamento"><span class="whatsapp-logo" aria-hidden="true"><svg viewBox="0 0 24 24" focusable="false"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.198.297-.767.966-.94 1.164-.173.198-.347.223-.644.074-.297-.148-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479s1.065 2.875 1.213 3.074c.149.198 2.095 3.2 5.076 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 0 1-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 0 1-1.51-5.26c.001-5.45 4.436-9.884 9.892-9.884a9.8 9.8 0 0 1 7.021 2.91 9.79 9.79 0 0 1 2.898 7.02c-.002 5.45-4.437 9.884-9.893 9.884m8.413-18.297A11.82 11.82 0 0 0 12.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.9 11.9 0 0 0 5.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.82 11.82 0 0 0-3.48-8.413Z"/></svg></span><strong>SOLICITE SEU ORÇAMENTO</strong></button>
    <section class="chat-panel" aria-label="Chat JLL Montagens" hidden>
      <header class="chat-header"><div><img class="chat-brand-logo" src="/assets/brand/jll-horizontal-reverse.svg" width="1000" height="300" alt="JLL Montagens"><strong>Atendimento online</strong></div><button class="chat-close" type="button" aria-label="Fechar chat">×</button></header>
      <div class="chat-ticket" hidden></div><div class="chat-body"></div>
      <form class="chat-composer" hidden><input class="chat-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><input class="chat-camera" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" hidden><div class="chat-source-options"><button class="chat-source-button chat-gallery-button" type="button" data-attach="gallery" aria-label="Anexar imagem da galeria" title="Anexar imagem"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M6.5 4.5h9a2 2 0 0 1 2 2v1h-2v-1h-9v11h1v2h-1a2 2 0 0 1-2-2v-11a2 2 0 0 1 2-2Zm4 3h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2h-7a2 2 0 0 1-2-2v-10a2 2 0 0 1 2-2Zm0 2v10h7v-10h-7Zm1 1.5a1.5 1.5 0 1 1 3 0 1.5 1.5 0 0 1-3 0Zm-2 6 2.3-2.5 1.7 1.8 1.3-1.4 2.7 3.1h-8Z"/></svg></button><button class="chat-source-button chat-camera-button" type="button" data-attach="camera" aria-label="Tirar foto com a câmera" title="Tirar foto"><svg aria-hidden="true" viewBox="0 0 24 24" focusable="false"><path d="M8 5h2l1.2-2h3.6L16 5h2a3 3 0 0 1 3 3v9a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V8a3 3 0 0 1 3-3h2Zm0 2H6a1 1 0 0 0-1 1v9a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V8a1 1 0 0 0-1-1h-2.2l-1.2-2h-2.4L10.8 7H8Zm4 1.5a4.5 4.5 0 1 1 0 9 4.5 4.5 0 0 1 0-9Zm0 2a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5Z"/></svg></button></div><input name="message" autocomplete="off" placeholder="Digite sua mensagem..." maxlength="2000"><button type="submit" aria-label="Enviar mensagem">➤</button></form>
    </section>`;
  document.body.appendChild(el);
  const launcher = el.querySelector('.chat-launcher'); const panel = el.querySelector('.chat-panel'); const body = el.querySelector('.chat-body'); const composer = el.querySelector('.chat-composer'); const ticket = el.querySelector('.chat-ticket'); const filePicker = composer.querySelector('.chat-file'); const cameraPicker = composer.querySelector('.chat-camera'); const attachButton = composer.querySelector('.chat-gallery-button'); const cameraButton = composer.querySelector('.chat-camera-button'); const isMobileDevice = matchMedia('(pointer: coarse)').matches || /Android|iPhone|iPad|iPod/i.test(navigator.userAgent); if(!isMobileDevice) cameraButton.hidden=true;
  const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
  const setOpen = open => { panel.hidden = !open; launcher.setAttribute('aria-expanded', String(open)); if(open){ if(state.conversation) loadMessages().catch(()=>renderHome()); else renderHome(); } };
  document.querySelectorAll('.quote-chat-link').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();setOpen(true)}));
  const renderHome = () => { composer.hidden = true; ticket.hidden = true; body.innerHTML = `<div class="chat-welcome"><img class="chat-mark" src="/assets/brand/jll-symbol-color.svg" width="320" height="320" alt=""><h2>Olá! Como podemos ajudar?</h2><p>Fale com nossa equipe sobre montagem de móveis e instalação de TV.</p><div class="chat-choice"><button type="button" data-action="new">Novo atendimento <span>→</span></button><button type="button" data-action="resume">Continuar atendimento <span>→</span></button></div>${state.conversation ? '<small class="chat-saved-note">Já existe um atendimento salvo neste dispositivo. Escolha “Continuar atendimento” para recuperá-lo.</small>' : ''}</div>`; };
  const formView = (kind) => { composer.hidden = true; ticket.hidden = true; const resume = kind === 'resume'; body.innerHTML = `<div class="chat-form-view"><button class="chat-back" type="button">← Voltar</button><h2>${resume ? 'Continuar atendimento' : 'Novo atendimento'}</h2><p>${resume ? 'Informe o telefone usado no atendimento para recuperar seu histórico.' : 'Informe seus dados para iniciar uma conversa com um especialista.'}</p>${resume ? '' : '<label>Nome<input name="customerName" autocomplete="name" required></label>'}<label>Telefone<input name="customerPhone" inputmode="tel" autocomplete="tel" placeholder="(21) 99999-9999" required></label><button class="chat-primary" type="button" data-submit="${resume ? 'resume' : 'new'}">${resume ? 'Buscar atendimento' : 'Iniciar conversa'} <span>→</span></button><p class="chat-error" role="alert"></p></div>`; };
  const renderConversation = () => { composer.hidden = false; ticket.hidden = false; ticket.textContent = `Atendimento #${state.conversation.ticketNumber}`; body.innerHTML = `<div class="chat-messages">${state.messages.map(message => { const senderType=String(message.sender_type||'').toUpperCase(); const senderClass=senderType==='ATENDENTE'?'from-attendant':senderType==='CLIENTE'?'from-client':'from-system'; const image = message.attachment_id ? `<button class="chat-image-message" type="button" data-image-url="/api/conversations/attachment?conversationId=${encodeURIComponent(state.conversation.id)}&messageId=${encodeURIComponent(message.id)}"><img src="/api/conversations/attachment?conversationId=${encodeURIComponent(state.conversation.id)}&messageId=${encodeURIComponent(message.id)}" alt="Imagem enviada pelo cliente" loading="lazy"></button>` : `<span>${escapeHtml(message.body || '')}</span>`; return `<div class="chat-message ${senderClass}">${image}<small>${new Date(message.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>`; }).join('')}</div>`; const messages = body.querySelector('.chat-messages'); const scrollToLatest=()=>{body.scrollTo({top:body.scrollHeight,left:0,behavior:'auto'});messages.scrollTop=messages.scrollHeight;}; scrollToLatest(); requestAnimationFrame(scrollToLatest); setTimeout(scrollToLatest,80); setTimeout(scrollToLatest,300); body.querySelectorAll('img').forEach(image=>image.addEventListener('load',scrollToLatest,{once:true})); };  const request = async (url, payload) => { const response = await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); const data = await response.json().catch(()=>({})); if(!response.ok){ const error=new Error(data.error || 'Não foi possível concluir.'); error.status=response.status; throw error; } return data; };
  const loadMessages = async () => { const data = await request('/api/conversations/resume',{phone:state.conversation.phone}); state.conversation=data.conversation; state.messages=data.messages || []; saveConversation(); renderConversation(); };
  el.addEventListener('click', async event => { const attachmentChoice=event.target.closest('[data-attach]'); if(attachmentChoice){ (attachmentChoice.dataset.attach==='camera'?cameraPicker:filePicker).click(); return; } const imageButton=event.target.closest('.chat-image-message'); if(imageButton){ const viewer=document.createElement('div'); viewer.className='chat-image-viewer'; viewer.innerHTML=`<button type="button" aria-label="Fechar imagem">×</button><img src="${imageButton.dataset.imageUrl}" alt="Imagem ampliada">`; viewer.onclick=()=>viewer.remove(); document.body.appendChild(viewer); return; } const action = event.target.closest('[data-action]')?.dataset.action; if(action) return formView(action); if(event.target.closest('.chat-back')) return renderHome(); const submit = event.target.closest('[data-submit]'); if(!submit) return; const form = event.target.closest('.chat-form-view'); const error = form.querySelector('.chat-error'); submit.disabled = true; error.textContent = ''; try { const phone=form.querySelector('[name="customerPhone"]').value; if(submit.dataset.submit === 'resume'){ const data=await request('/api/conversations/resume',{phone}); state.conversation=data.conversation; state.messages=data.messages || []; saveConversation(); renderConversation(); } else { const data=await request('/api/conversations/create',{name:form.querySelector('[name="customerName"]').value,phone}); if(data.existing){ error.textContent='Já existe um atendimento aberto para este telefone. Recuperar atendimento?'; const confirm=document.createElement('button'); confirm.type='button'; confirm.className='chat-primary'; confirm.textContent='Continuar atendimento'; confirm.onclick=async()=>{state.conversation=data.conversation; await loadMessages();}; form.appendChild(confirm); } else { state.conversation=data.conversation; state.messages=[{sender_type:'system',body:data.message,created_at:new Date().toISOString()}]; saveConversation(); jllConversions.trackNewConversation(data.conversation.id); renderConversation(); } } } catch(exception){ error.textContent=exception.message; submit.disabled=false; if(submit.dataset.submit === 'resume' && exception.status === 404){ const phone=form.querySelector('[name="customerPhone"]').value; const newButton=document.createElement('button'); newButton.type='button'; newButton.className='chat-primary'; newButton.textContent='Abrir novo atendimento'; newButton.onclick=()=>{formView('new'); body.querySelector('[name="customerPhone"]').value=phone;}; form.appendChild(newButton); } } });
  composer.addEventListener('submit', async event => { event.preventDefault(); const input=composer.elements.message; const value=input.value.trim(); if(!value || !state.conversation) return; input.disabled=true; try { const data=await request('/api/conversations/message',{conversationId:state.conversation.id,body:value}); state.messages.push(data.message); saveConversation(); input.value=''; renderConversation(); } catch(exception){ alert(exception.message); } finally { input.disabled=false; input.focus(); } });
  const prepareImage = file => new Promise((resolve,reject)=>{ const reader=new FileReader(); reader.onerror=reject; reader.onload=()=>{ const image=new Image(); image.onerror=reject; image.onload=async()=>{ const limit=1600; const scale=Math.min(1,limit/Math.max(image.naturalWidth,image.naturalHeight)); const canvas=document.createElement('canvas'); canvas.width=Math.max(1,Math.round(image.naturalWidth*scale)); canvas.height=Math.max(1,Math.round(image.naturalHeight*scale)); canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height); const qualities=[.86,.74,.62,.5,.4]; let blob=null; for(const quality of qualities){ blob=await new Promise(done=>canvas.toBlob(done,'image/jpeg',quality)); if(blob && blob.size<=2.8*1024*1024) break; } if(!blob) return reject(new Error('Não foi possível preparar a imagem.')); const fileReader=new FileReader(); fileReader.onload=()=>resolve({data:String(fileReader.result).split(',')[1],mimeType:'image/jpeg',fileName:file.name.replace(/\.[^.]+$/,'')+'.jpg'}); fileReader.onerror=reject; fileReader.readAsDataURL(blob); }; image.src=String(reader.result); }; reader.readAsDataURL(file); });
  const sendImageFile = async file => { if(!file||!state.conversation)return; if(!file.type.startsWith('image/')){alert('Escolha uma imagem.');return} attachButton.disabled=true; attachButton.setAttribute('aria-busy','true'); try{const prepared=await prepareImage(file);const data=await request('/api/conversations/photo',{conversationId:state.conversation.id,fileName:prepared.fileName,mimeType:prepared.mimeType,data:prepared.data});state.messages.push(data.message);saveConversation();renderConversation()}catch(exception){alert(exception.message)}finally{attachButton.disabled=false;attachButton.removeAttribute('aria-busy');filePicker.value='';cameraPicker.value='';} };
  filePicker.addEventListener('change',()=>sendImageFile(filePicker.files?.[0]));
  cameraPicker.addEventListener('change',()=>sendImageFile(cameraPicker.files?.[0]));  launcher.addEventListener('click',()=>setOpen(true)); el.querySelector('.chat-close').addEventListener('click',()=>setOpen(false)); renderHome();
})();














